            <span class="actions">
              <button @click="moveUp(index)" :disabled="index === 0">Up</button>
              <button @click="moveDown(index)" :disabled="index === stack.length - 1">Down</button>
              <button @click="removeItem(index)">Remove</button>
            </span>
          </li>
